import java.util.Scanner;

public class p723b {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int inputSize = scanner.nextInt();
        String inputString = scanner.next();
        int maxUnderscoreCount = 0, totalWords = 0, lastSeparator = -1;
        boolean inParenthesesState = false;
        int totalLen = inputString.length();

        for (int index = 0; index < totalLen; index++) {
            char ch = inputString.charAt(index);
            if (ch == '_' && !inParenthesesState && maxUnderscoreCount < index - lastSeparator - 1) {
                maxUnderscoreCount = index - lastSeparator - 1;
            }
            if (ch == '_' && inParenthesesState && index - lastSeparator > 1) {
                totalWords++;
            }
            if (ch == '(') {
                inParenthesesState = true;
                if (maxUnderscoreCount < index - lastSeparator - 1) {
                    maxUnderscoreCount = index - lastSeparator - 1;
                }
            }
            if (ch == ')') {
                inParenthesesState = false;
                if (index - lastSeparator > 1) {
                    totalWords++;
                }
            }
            if (ch == '_' || ch == '(' || ch == ')') {
                lastSeparator = index;
            }
        }
        if (maxUnderscoreCount < totalLen - lastSeparator - 1) {
            maxUnderscoreCount = totalLen - lastSeparator - 1;
        }
        System.out.println(maxUnderscoreCount + " " + totalWords);
    }
}
